import { randomUUID } from 'crypto';
import { createLogger } from '../index-core';
import type {
  TelemetryContext,
  WorkItemInitiator,
} from '../types/change-request-types';

const log = createLogger('SessionBridgeService');

type SessionStatus = 'IDLE' | 'WATCHING' | 'APPLYING' | 'READY';
export type DevServerOwnership = 'rivet_owned' | 'external' | 'none';
export type DevServerHealthReason =
  'healthy' | 'upstream_unreachable' | 'rivet_unreachable' | 'unknown';

export type DevServerHealth = {
  ownership: DevServerOwnership;
  host: string | null;
  port: number | null;
  isReachable: boolean | null;
  reason: DevServerHealthReason;
  lastCheckedAt: number | null;
  startedByRivet: boolean;
};

export type BatchChannelKind = 'apply' | 'variant';

export type ChannelDepth = {
  queued: number;
  leased: number;
};

export type ActiveLeaseMetadata = {
  kind: BatchChannelKind;
  requestId: string;
  leaseId: string;
  leasedAt: number;
  ageMs: number;
  changeCount: number;
  sourceFileCount: number;
  mergedFrom: number;
  mergedRequestCount: number;
  mergedRequestIds: string[];
  initiator: WorkItemInitiator;
};

export type QueuedBatchMetadata = {
  kind: BatchChannelKind;
  requestId: string;
  enqueuedAt: number;
  ageMs: number;
  changeCount: number;
  initiator: WorkItemInitiator;
};

export type ResolvedRunnerInfo =
  | { mode: 'runner'; vendor: string; source: string; binaryPath?: string }
  | { mode: 'unavailable'; reason?: string };

export type RunnerMismatch = {
  agent: string;
  model?: string;
  at: number;
};

export type SessionRuntimeInfo = {
  sessionInitiator: WorkItemInitiator | null;
  resolvedRunner: ResolvedRunnerInfo | null;
  runnerMismatches: RunnerMismatch[];
};

export type WatcherLiveness = {
  watcherActive: boolean;
  pendingCount: number;
  leasedVariantRequests: number;
  oldestPendingChangeEnqueuedAt: number | null;
  oldestPendingChangeAgeMs: number | null;
};

const EMPTY_DEV_SERVER_HEALTH: DevServerHealth = {
  ownership: 'none',
  host: null,
  port: null,
  isReachable: null,
  reason: 'unknown',
  lastCheckedAt: null,
  startedByRivet: false,
};

export class SessionBridgeService {
  private sessionId: string | null = null;
  private projectPath: string | null = null;
  private feedback: string[] = [];
  private status: SessionStatus = 'IDLE';
  private roundsCompleted = 0;
  private telemetryContext: TelemetryContext | null = null;
  private _setVariantTarget: ((port: number | null) => void) | null = null;
  private _variantLookup: ((label: string) => number | null) | null = null;
  private _isVariantPortAllowed: ((port: number) => boolean) | null = null;
  private statusAccessToken: string | null = null;
  private baseDevServerHealth: DevServerHealth | null = null;
  private devServerHealth: DevServerHealth = { ...EMPTY_DEV_SERVER_HEALTH };
  private sessionInitiator: WorkItemInitiator | null = null;
  private resolvedRunner: ResolvedRunnerInfo | null = null;
  private runnerMismatches: RunnerMismatch[] = [];
  private livenessListeners = new Set<() => void>();

  startSession(projectPath: string): string {
    if (this.sessionId) {
      log.warn('Session already active, ending previous session');
      this.endSession();
    }

    this.sessionId = randomUUID();
    this.projectPath = projectPath;
    this.feedback = [];
    this.status = 'IDLE';
    this.roundsCompleted = 0;
    this.telemetryContext = null;
    this.sessionInitiator = null;
    this.resolvedRunner = null;
    this.runnerMismatches = [];
    this.baseDevServerHealth = null;
    this.devServerHealth = { ...EMPTY_DEV_SERVER_HEALTH };
    this._variantLookup = null;
    this._isVariantPortAllowed = null;
    this.statusAccessToken = null;
    log.info(`Session started: ${this.sessionId} for ${projectPath}`);
    this.notifyLivenessChange();
    return this.sessionId;
  }

  reportFeedback(message: string): void {
    if (!this.sessionId) {
      log.warn('Cannot report feedback: no active session');
      return;
    }

    const normalized = message.startsWith('__RIVET_')
      ? message
      : message.replace(/\\n/g, '\n').replace(/\\t/g, '\t');
    this.feedback.push(normalized);
    log.info(`Feedback reported: ${normalized}`);
  }

  getFeedback(): string[] {
    return this.feedback;
  }

  getStatus(): SessionStatus {
    return this.status;
  }

  setStatus(status: SessionStatus): void {
    if (this.status !== status) {
      log.info(`Session status changed: ${this.status} -> ${status}`);
      this.status = status;
    }
  }

  isActive(): boolean {
    return this.sessionId !== null;
  }

  getSessionId(): string | null {
    return this.sessionId;
  }

  getProjectPath(): string | null {
    return this.projectPath;
  }

  hasUnfinishedWork(): boolean {
    return false;
  }

  getChannelDepth(_kind: BatchChannelKind): ChannelDepth {
    return { queued: 0, leased: 0 };
  }

  getActiveLeaseMetadata(): ActiveLeaseMetadata[] {
    return [];
  }

  getQueuedBatchMetadata(): QueuedBatchMetadata[] {
    return [];
  }

  getActiveRunCorrelation(): null {
    return null;
  }

  getSettledRequestIds(): string[] {
    return [];
  }

  getRoundsCompleted(): number {
    return this.roundsCompleted;
  }

  setSessionRuntimeInfo(info: {
    sessionInitiator?: WorkItemInitiator | null;
    resolvedRunner?: ResolvedRunnerInfo | null;
  }): void {
    if ('sessionInitiator' in info) {
      this.sessionInitiator = info.sessionInitiator ?? null;
    }
    if ('resolvedRunner' in info) {
      this.resolvedRunner = info.resolvedRunner ?? null;
      log.info(`Apply runner resolved: ${JSON.stringify(this.resolvedRunner)}`);
    }
  }

  getSessionRuntimeInfo(): SessionRuntimeInfo {
    return {
      sessionInitiator: this.sessionInitiator,
      resolvedRunner: this.resolvedRunner,
      runnerMismatches: [...this.runnerMismatches],
    };
  }

  recordRunnerMismatch(initiator: WorkItemInitiator): void {
    if (initiator.kind !== 'agent' || initiator.agent === 'unknown') return;
    this.runnerMismatches.push({
      agent: initiator.agent,
      ...(initiator.model ? { model: initiator.model } : {}),
      at: Date.now(),
    });
  }

  getTelemetryContext(): TelemetryContext | null {
    return this.telemetryContext;
  }

  updateTelemetryContext(context?: TelemetryContext): void {
    if (!context) return;
    const nextContext: TelemetryContext = {
      ...this.telemetryContext,
      ...context,
    };
    if (
      nextContext.browserSessionId === undefined &&
      nextContext.browserDistinctId === undefined
    ) {
      return;
    }
    this.telemetryContext = nextContext;
  }

  getDevServerHealth(): DevServerHealth {
    return this.devServerHealth;
  }

  setDevServerContext(context: {
    ownership: DevServerOwnership;
    host?: string | null;
    port?: number | null;
    startedByRivet: boolean;
  }): void {
    this.devServerHealth = {
      ...this.devServerHealth,
      ownership: context.ownership,
      host: context.host ?? null,
      port: context.port ?? null,
      startedByRivet: context.startedByRivet,
    };
    this.baseDevServerHealth = { ...this.devServerHealth };
  }

  updateDevServerHealth(update: {
    isReachable?: boolean | null;
    reason?: DevServerHealthReason;
    lastCheckedAt?: number | null;
  }): void {
    this.devServerHealth = {
      ...this.devServerHealth,
      isReachable:
        update.isReachable === undefined
          ? this.devServerHealth.isReachable
          : update.isReachable,
      reason: update.reason ?? this.devServerHealth.reason,
      lastCheckedAt:
        update.lastCheckedAt === undefined
          ? this.devServerHealth.lastCheckedAt
          : update.lastCheckedAt,
    };
    if (
      this.baseDevServerHealth &&
      this.baseDevServerHealth.ownership === this.devServerHealth.ownership &&
      this.baseDevServerHealth.host === this.devServerHealth.host &&
      this.baseDevServerHealth.port === this.devServerHealth.port
    ) {
      this.baseDevServerHealth = { ...this.devServerHealth };
    }
  }

  registerVariantTargetSetter(fn: (port: number | null) => void): void {
    this._setVariantTarget = fn;
  }

  registerVariantLookup(fn: (variantKey: string) => number | null): void {
    this._variantLookup = fn;
  }

  registerVariantPortAllowlist(fn: (port: number) => boolean): void {
    this._isVariantPortAllowed = fn;
  }

  lookupVariantPort(variantKey: string): number | null {
    return this._variantLookup?.(variantKey) ?? null;
  }

  isVariantPortAllowed(port: number): boolean {
    return this._isVariantPortAllowed?.(port) ?? false;
  }

  setStatusAccessToken(token: string): void {
    this.statusAccessToken = token;
  }

  hasStatusAccessToken(): boolean {
    return this.statusAccessToken !== null;
  }

  isStatusAccessTokenValid(token: string | null | undefined): boolean {
    return Boolean(token) && token === this.statusAccessToken;
  }

  switchPreviewPort(port: number | null): void {
    if (!this._setVariantTarget) {
      log.warn(
        `switchPreviewPort(${port}) called but no variant target setter registered`,
      );
    }
    this._setVariantTarget?.(port);

    if (port !== null) {
      this.devServerHealth = {
        ownership: 'rivet_owned',
        host: 'localhost',
        port,
        isReachable: true,
        reason: 'healthy',
        lastCheckedAt: Date.now(),
        startedByRivet: true,
      };
      this.reportFeedback('__RIVET_RELOAD_PREVIEW__');
      return;
    }

    if (this.baseDevServerHealth) {
      this.devServerHealth = { ...this.baseDevServerHealth };
    }
    this.reportFeedback('__RIVET_RELOAD_PREVIEW__');
  }

  endSession(): number {
    const rounds = this.roundsCompleted;
    if (this.sessionId) {
      log.info(`Session ended: ${this.sessionId}`);
    }
    this.sessionId = null;
    this.projectPath = null;
    this.feedback = [];
    this.status = 'IDLE';
    this.roundsCompleted = 0;
    this.telemetryContext = null;
    this.sessionInitiator = null;
    this.resolvedRunner = null;
    this.runnerMismatches = [];
    this.baseDevServerHealth = null;
    this.devServerHealth = { ...EMPTY_DEV_SERVER_HEALTH };
    this._variantLookup = null;
    this._isVariantPortAllowed = null;
    this.statusAccessToken = null;
    this.notifyLivenessChange();
    return rounds;
  }

  getWatcherLiveness(_now: number = Date.now()): WatcherLiveness {
    return {
      watcherActive: false,
      pendingCount: 0,
      leasedVariantRequests: 0,
      oldestPendingChangeEnqueuedAt: null,
      oldestPendingChangeAgeMs: null,
    };
  }

  onWatcherLivenessChange(listener: () => void): () => void {
    this.livenessListeners.add(listener);
    return () => {
      this.livenessListeners.delete(listener);
    };
  }

  pendingVariantRequestCount(): number {
    return 0;
  }

  private notifyLivenessChange(): void {
    for (const listener of this.livenessListeners) {
      listener();
    }
  }
}
